import { assertEmptyRest } from './utils/assertUint8.mjs'
import { fromCompressInput } from './utils/input.mjs'
import { fromUint8Super } from './utils/output.mjs'

import zlib from 'node:zlib'

const makeCallback = (resolve, reject) => (err, res) => {
  if (err) return reject(err)
  resolve(res)
}

const wrap =
  (f, isCompress = false) =>
  async (data, { format, ...rest } = {}) => {
    assertEmptyRest(rest)
    const chunks = fromCompressInput(data, isCompress) // only compression can be called on strings
    const dataBytes = chunks.length === 1 ? chunks[0] : Buffer.concat(chunks) // TODO: optimize with streaming
    const buf = await new Promise((resolve, reject) => f(dataBytes, makeCallback(resolve, reject)))
    return fromUint8Super(buf, format)
  }

export const gzip = wrap(zlib.gzip, true)
export const gunzip = wrap(zlib.gunzip)
export const deflate = wrap(zlib.deflate, true)
export const inflate = wrap(zlib.inflate)
